{"command":"python3 - <<'PY'
import zipfile, re
for jar, want in [("/testbed/tmpl-svc/vendor/java/commons-text-1.10.0.jar","1.10.0"),
                  ("/testbed/tmpl-svc/vendor/java/commons-lang3-3.12.0.jar","3.12.0")]:
    with zipfile.ZipFile(jar) as zf:
        for n in zf.namelist():
            if n.endswith("/pom.properties"):
                body = zf.read(n).decode("utf-8","replace")
                v = re.search(r"^version=(.+)$", body, re.M).group(1)
                a = re.search(r"^artifactId=(.+)$", body, re.M).group(1)
                print(f"{a}={v} (expected {want}) -> {'OK' if v==want else 'MISMATCH'}")
